<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,shallowReactive,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useSession} from '../../session'
import {ApiError} from '../../api'
import {ObjectLease} from '../../object-lease'
import {customerPortal} from '../../portal'
import QuoteDraftComposer from './QuoteDraftComposer.vue'
import {quoteBody,confirmationBody,yuanFromCents,type QuoteDraft} from './quote-draft'
import {canReadFinance,canWriteFinance,canConfirmFinance,financeOwner,financeTransport,parseGroup,parseQuote,parseReferences,uuid,type FinanceGroup,type FinanceQuote,type QuoteReferences} from './finance-client'
import {FinanceWork,retainedFinance,type FinanceAction} from './finance-work'
import {canReadMoney} from '../money/money-client'
import {loadPartQuoteOptions,type PartQuotePage} from './part-quote-catalog'
const auth=useSession(),route=useRoute(),router=useRouter(),ticketInput=ref(''),quoteInput=ref(''),consent=ref(false),reason=ref(''),newQuote=ref(crypto.randomUUID()),replaces=ref<string[]>([]),before=ref<string|null>(null),draft=ref<QuoteDraft|null>(null)
let alive=true
const partPage=ref(1)
const ticketId=computed(()=>String(route.params.id??'')),quoteId=computed(()=>String(route.params.quoteId??'')),identity=computed(()=>JSON.stringify(financeOwner(auth))),context=()=>JSON.stringify([identity.value,route.fullPath]),wire=financeTransport(auth,()=>alive),hasTarget=computed(()=>uuid(ticketId.value)),readable=computed(()=>canReadFinance(auth.identity))
const group=reactive(new ObjectLease<FinanceGroup>(auth,context,async()=>{const stamp=context();return parseGroup(await wire.send('GET','/finance/tickets/'+ticketId.value+'/group',undefined,()=>context()===stamp))})),quote=reactive(new ObjectLease<FinanceQuote>(auth,context,async()=>{if(!group.value||!uuid(quoteId.value))throw Error('请先查询当前费用组');const stamp=context(),q=quoteId.value;return parseQuote(await wire.send('GET','/finance/groups/'+group.value.groupId+'/quotes/'+q,undefined,()=>context()===stamp),q)}))
const referenceContext=()=>context()+':'+before.value,references=reactive(new ObjectLease<QuoteReferences>(auth,referenceContext,async()=>{if(!group.value)throw Error('请先查询费用组');const stamp=referenceContext();return parseReferences(await wire.send('GET','/ticket/tickets/'+ticketId.value+'/finance-quote-references'+(before.value?'?beforeGeneration='+before.value:''),undefined,()=>referenceContext()===stamp),group.value.groupId,before.value)}))
const partsContext=()=>context()+':parts:'+partPage.value
const partCatalog=reactive(new ObjectLease<PartQuotePage>(auth,partsContext,async()=>{
 const owner=financeOwner(auth),stamp=partsContext()
 if(!owner||!canWriteFinance(auth.identity))throw Error('当前身份不能查询报价备件申请')
 return loadPartQuoteOptions(wire,owner,ticketId.value,partPage.value,()=>partsContext()===stamp)
}))
async function refreshParts(){draft.value=null;consent.value=false;await partCatalog.refresh()}
const currentObject=computed(()=>readable.value&&!!group.value),writeAllowed=(a:FinanceAction)=>!!financeOwner(auth)&&currentObject.value&&(a==='CUSTOMER_QUOTE_CONFIRMED'?canConfirmFinance(auth.identity)&&!!quote.value&&quote.value.current&&quote.value.chargesCustomer&&quote.value.customerDecision==='PENDING'&&quote.value.termination==='NONE':canWriteFinance(auth.identity))
const work=shallowReactive(new FinanceWork(wire,()=>financeOwner(auth),a=>a==='GROUP_OPEN'?!!financeOwner(auth)&&canWriteFinance(auth.identity)&&hasTarget.value:writeAllowed(a),o=>reactive(o),()=>crypto.randomUUID(),e=>{if(e instanceof ApiError&&[401,403,404,503].includes(e.status)){group.clear('当前对象权限或依赖无法确认，请重新查询');quote.clear();consent.value=false;draft.value=null}}))
const draftContext=computed(()=>group.value&&currentObject.value?{ticketId:ticketId.value,expectedVersion:group.value.version,quoteId:newQuote.value}:undefined),customerLink=computed(()=>group.value&&quote.value?'/customer/tickets/'+ticketId.value+'/finance/quotes/'+quote.value.quoteId:''),recoveries=computed(()=>{const o=financeOwner(auth);return o?Array.from(retainedFinance.entries()).flatMap(([k,v])=>{const [tenant,actor,ticket]=JSON.parse(k);return tenant===o.tenant&&actor===o.actor?[{ticket,key:v.key}]:[]}):[]})
function clearForm(){consent.value=false;draft.value=null;replaces.value=[];reason.value=''}
async function refresh(reset=true){if(reset)clearForm();const oldVersion=group.value?.version;if(!hasTarget.value||!readable.value)return;await group.refresh();if(oldVersion!==group.value?.version)clearForm();if(group.value)await references.refresh();if(group.value&&canWriteFinance(auth.identity))await partCatalog.refresh();if(group.value&&uuid(quoteId.value))await quote.refresh()}
async function openTicket(){if(uuid(ticketInput.value))await router.push('/tickets/'+ticketInput.value+'/finance')}
async function openQuote(){if(hasTarget.value&&uuid(quoteInput.value))await router.push('/tickets/'+ticketId.value+'/finance/quotes/'+quoteInput.value)}
async function openCurrent(){if(group.value?.currentQuoteId)await router.push('/tickets/'+ticketId.value+'/finance/quotes/'+group.value.currentQuoteId)}
function receiveDraft(body:ReturnType<typeof quoteBody>){try{const{operationId:_,...d}=body;draft.value={...d,replaces:[...replaces.value]};quoteBody(draft.value,crypto.randomUUID());consent.value=false}catch(e){work.message=e instanceof Error?e.message:'草稿无效'}}
async function submitDraft(){if(!draft.value||!consent.value||!group.value||!writeAllowed('QUOTE_SUBMITTED'))return;const d=draft.value;if(d.expectedVersion!==group.value.version||d.ticketId!==ticketId.value||d.quoteId!==newQuote.value){draft.value=null;return}await work.start('QUOTE_SUBMITTED',group.value.groupId,d.quoteId,{...d});consent.value=false;draft.value=null}
async function confirmQuote(){if(!consent.value||!group.value||!quote.value||!writeAllowed('CUSTOMER_QUOTE_CONFIRMED'))return;const{operationId:_,...body}=confirmationBody(crypto.randomUUID(),group.value.version,quote.value.quoteVersion);await work.start('CUSTOMER_QUOTE_CONFIRMED',group.value.groupId,quote.value.quoteId,body);consent.value=false}
async function abort(){try{await work.abort(reason.value)}catch(e){work.message=e instanceof Error?e.message:'原因无效'}}
async function next(){const q=work.operation?.receipt?.quoteId;work.next();newQuote.value=crypto.randomUUID();if(q&&quoteId.value!==q)await router.push('/tickets/'+ticketId.value+'/finance/quotes/'+q);else await refresh()}
watch(()=>[identity.value,route.fullPath],()=>{work.unbind();group.clear();quote.clear();references.clear();partCatalog.clear();partPage.value=1;before.value=null;clearForm();newQuote.value=crypto.randomUUID();if(hasTarget.value)work.bind(ticketId.value);void refresh()},{immediate:true,flush:'sync'})
watch(replaces,()=>{draft.value=null;consent.value=false},{deep:true})
watch(()=>partCatalog.value,()=>{draft.value=null;consent.value=false})
function visibility(){clearForm();if(document.visibilityState==='hidden'){group.clear();quote.clear();references.clear();partCatalog.clear()}else void refresh()}
document.addEventListener('visibilitychange',visibility)
let last=Date.now();const timer=setInterval(()=>{group.expire();quote.expire();references.expire();partCatalog.expire();if(Date.now()-last>=25000){last=Date.now();if(document.visibilityState!=='hidden'&&!work.busy)void refresh(false)}},1000)
onBeforeUnmount(()=>{alive=false;work.dispose();group.dispose();quote.dispose();references.dispose();partCatalog.dispose();clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
const actionLabel=(a:FinanceAction)=>({GROUP_OPEN:'开通费用组',QUOTE_SUBMITTED:'提交报价',CUSTOMER_QUOTE_CONFIRMED:'客户确认报价'}[a])
</script>
<template>
<RouterLink v-if="group.value && canReadMoney(auth.identity) && !customerPortal" :to="'/money/'+group.value.groupId">当前费用组线下资金与不可变流水</RouterLink>
<section class="page-heading"><RouterLink to="/tickets">← 工单</RouterLink><h1>{{customerPortal?'客户报价确认':'费用报价'}}</h1><p>报价、客户确认、内部审批、应收和实际收付款是独立事实；本页不办理收款退款或付费领料。</p></section>
<section class="panel"><label>工单 UUID<input v-model="ticketInput" autocomplete="off"></label><button :disabled="!uuid(ticketInput)" @click="openTicket">查询授权工单费用组</button><p v-if="!readable" role="alert">当前账号没有费用读取能力；企业管理员资格和企业范围由服务端逐次核验。</p><p v-if="recoveries.length">本账号内存中保留的原操作：</p><p v-for="r in recoveries" :key="r.key"><RouterLink :to="'/tickets/'+r.ticket+'/finance'">恢复原UUID {{r.key}}</RouterLink></p></section>
<section v-if="hasTarget" class="panel"><h2>当前费用组</h2><p>工单 {{ticketId}}</p><button :disabled="group.busy||!readable" @click="refresh()">重新核验当前费用组和报价</button><p v-if="group.busy">正在核验当前对象…</p><p v-if="group.error" role="alert">{{group.error}}。查询失败不表示未提交，也不会释放报价冻结。</p><p v-if="group.value">费用组 {{group.value.groupId}} · 当前组版本 {{group.value.version}}</p><button v-if="!group.value&&!work.operation&&canWriteFinance(auth.identity)" :disabled="work.busy" @click="work.start('GROUP_OPEN',null,null,{})">显式开通此工单费用组</button>
<template v-if="currentObject"><RouterLink v-if="customerPortal" :to="'/money-reviews/'+group.value!.groupId">查询应收降低申请</RouterLink><h3>已提交报价引用</h3><p>目录仅证明报价已提交；当前状态与确认资格须打开后重新核验。</p><p v-if="references.error" role="alert">{{references.error}}</p><p v-if="references.value&&references.value.items.length===0">本次尚未观察到已提交引用；协调可能仍在收敛，请重新查询，不能据此判断没有报价。</p><ul><li v-for="q in references.value?.items" :key="q.quoteId"><RouterLink :to="'/tickets/'+ticketId+'/finance/quotes/'+q.quoteId">报价版本 {{q.quoteVersion}} · {{q.quoteId}}</RouterLink></li></ul><button v-if="before" @click="before=null;references.clear();references.refresh()">第一页报价</button><button v-if="references.value?.nextBeforeGeneration" @click="before=references.value!.nextBeforeGeneration;references.clear();references.refresh()">较早报价</button><button v-if="group.value?.currentQuoteId" @click="openCurrent">查看当前报价</button><label>报价 UUID<input v-model="quoteInput" autocomplete="off"></label><button :disabled="!uuid(quoteInput)" @click="openQuote">查看此报价原版本</button></template></section>
<section v-if="hasTarget&&uuid(quoteId)" class="panel"><p v-if="quote.error" role="alert">{{quote.error}}</p><template v-if="quote.value&&currentObject"><h2>{{quote.value.current?'当前报价':'历史报价（只读）'}}</h2><p>报价 {{quote.value.quoteId}} · 不可变报价版本 {{quote.value.quoteVersion}}</p><p>{{quote.value.pricingDescription}}</p><p>{{quote.value.chargesCustomer?'本报价向客户收费':'本报价不向客户收费'}} · 客户状态 {{quote.value.customerDecision}} · 终止状态 {{quote.value.termination}}</p><ul><li v-for="l in quote.value.lines" :key="l.id">{{l.kind}} · {{yuanFromCents(l.amountCents)}} 元</li></ul><p>报价总额 {{yuanFromCents(quote.value.lines.reduce((n,l)=>n+BigInt(l.amountCents),0n).toString())}} 元</p><p>本地审批意图 {{quote.value.approvalRequestState}}；不表示内部审批通过、应收或已收款。</p><p v-if="!customerPortal"><a :href="customerLink">客户报价页面链接</a>（客户须以本企业当前管理员登录）</p>
<template v-if="!work.operation&&writeAllowed('CUSTOMER_QUOTE_CONFIRMED')"><label><input v-model="consent" type="checkbox">我已核对本报价内容与原报价版本，明确确认本次报价</label><button :disabled="!consent||work.busy" @click="confirmQuote">确认此原版本报价</button></template>
</template></section>
<section v-if="currentObject&&canWriteFinance(auth.identity)&&!work.operation" class="panel"><h2>编制新报价</h2><p>提交会取得新代际双owner冻结；依赖未就绪时保留原UUID，不能重复换键。新报价明细不会隐式替换旧项。</p><template v-if="quote.value?.current"><p>明确选择本次替换的当前报价明细；不选表示新增：</p><label v-for="l in quote.value.lines" :key="l.id"><input v-model="replaces" type="checkbox" :value="l.id">替换 {{l.kind}} {{yuanFromCents(l.amountCents)}}元（{{l.id}}）</label></template><section><h3>当前客户付费备件申请目录</h3><p v-if="partCatalog.error" role="alert">{{partCatalog.error}}</p><p v-if="partCatalog.busy">正在核验批准申请及备件单位…</p><button :disabled="partCatalog.busy" @click="refreshParts">重新核验报价备件目录</button><button :disabled="partPage<=1||partCatalog.busy" @click="partPage--;partCatalog.clear();refreshParts()">上一页备件申请</button><button :disabled="!partCatalog.value||partPage*20>=partCatalog.value.total||partCatalog.busy" @click="partPage++;partCatalog.clear();refreshParts()">下一页备件申请</button><p v-if="partCatalog.value&&!partCatalog.value.items.length">本页没有当前已批准的客户付费备件申请。</p></section><QuoteDraftComposer :key="newQuote" :context="draftContext" :part-options="partCatalog.value?.items" @draft="receiveDraft"/><template v-if="draft"><p>待提交预览：{{draft.lines.length}}项，替换{{draft.replaces.length}}项；组版本{{draft.expectedVersion}}。</p><label><input v-model="consent" type="checkbox">核对本次原参数并明确提交</label><button :disabled="!consent||work.busy" @click="submitDraft">提交本报价</button></template></section>
<section v-if="work.operation" class="panel"><h2>原费用操作恢复</h2><p>{{actionLabel(work.operation.action)}} · 原UUID {{work.operation.key}} · {{work.operation.state}}</p><p>查询只核对原结果，不自动重发、不换键。404不证明未执行；401/403/503不放行。</p><template v-if="currentObject"><pre>{{work.operation.body}}</pre><p v-if="work.operation.source">原源状态 {{work.operation.source.sourceState}}；不是全局owner释放证明。</p><p v-if="work.operation.receipt">历史回执组版本 {{work.operation.receipt.groupVersion}}</p></template><button :disabled="work.busy" @click="work.recover()">查询原操作UUID</button><button v-if="['NOT_OBSERVED','IN_PROGRESS'].includes(work.operation.state)&&!work.operation.abortBody&&(work.operation.action==='GROUP_OPEN'?canWriteFinance(auth.identity):writeAllowed(work.operation.action))" :disabled="work.busy" @click="work.recover(false)">显式原UUID原参数继续</button><template v-if="work.operation.source&&writeAllowed('QUOTE_SUBMITTED')&&['IN_PROGRESS','UNKNOWN'].includes(work.operation.state)"><label>明确中止原因<textarea v-model="reason" :disabled="!!work.operation.abortBody"/></label><button :disabled="work.busy" @click="abort">{{work.operation.abortBody?'显式原UUID原原因恢复中止':'显式中止原报价意图'}}</button></template><button v-if="['SUCCEEDED','ABORTED'].includes(work.operation.state)" :disabled="work.busy" @click="next">明确查询当前状态并准备下一动作</button></section><p v-if="work.message" class="notice" role="status">{{work.message}}</p>
</template>
<style scoped>label{display:block;margin:12px 0}input:not([type=checkbox]),textarea{padding:9px;font:inherit;max-width:100%;width:460px;box-sizing:border-box}button{margin:6px;padding:9px;font:inherit}pre,p{overflow-wrap:anywhere;white-space:pre-wrap}a{margin:6px}</style>
